program = '''from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    boxes = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != 0 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        q.append((yy, xx))
            rs = [p[0] for p in cells]
            cs = [p[1] for p in cells]
            boxes.append((min(rs), max(rs), min(cs), max(cs)))

    side = max(max(r1-r0+1, c1-c0+1) for r0, r1, c0, c1 in boxes)
    tiles = []
    for r0, r1, c0, c1 in boxes:
        ir0, ir1 = r0 + 1, min(r0 + side - 1, r1 + 1)
        ic0, ic1 = c0 + 1, min(c0 + side - 1, c1 + 1)
        if ir0 >= ir1 or ic0 >= ic1:
            continue
        vals = [grid[y][x] for y in range(ir0, ir1) for x in range(ic0, ic1)]
        color, count = Counter(vals).most_common(1)[0]
        if color != 0 and count == len(vals):
            tiles.append({'r': r0, 'r1': r1, 'c': c0, 'c1': c1, 'color': color})

    counts = Counter(t['color'] for t in tiles)
    if not counts:
        return out
    background = counts.most_common(1)[0][0]
    active = set(counts) - {background}

    def paint(y, x, color):
        if out[y][x] == 0:
            out[y][x] = color

    by_row = {}
    by_col = {}
    for t in tiles:
        by_row.setdefault(t['r'], []).append(t)
        by_col.setdefault(t['c'], []).append(t)

    for row_tiles in by_row.values():
        row_tiles.sort(key=lambda t: t['c'])
        for color in active:
            indices = [i for i, t in enumerate(row_tiles) if t['color'] == color]
            if len(indices) < 2:
                continue
            lo, hi = min(indices), max(indices)
            for i in range(lo, hi):
                a, b = row_tiles[i], row_tiles[i+1]
                for y in range(a['r'] + 1, min(a['r'] + side - 1, h)):
                    for x in range(a['c1'] + 1, b['c']):
                        paint(y, x, color)

    for col_tiles in by_col.values():
        col_tiles.sort(key=lambda t: t['r'])
        for color in active:
            indices = [i for i, t in enumerate(col_tiles) if t['color'] == color]
            if len(indices) < 2:
                continue
            lo, hi = min(indices), max(indices)
            for i in range(lo, hi):
                a, b = col_tiles[i], col_tiles[i+1]
                for y in range(a['r1'] + 1, b['r']):
                    for x in range(a['c'] + 1, min(a['c'] + side - 1, w)):
                        paint(y, x, color)
    return out
'''
